    AS x(slug text,name text,description text,url text,metadata jsonb)
  LOOP
    SELECT * INTO v_existing FROM providers.apis WHERE slug=v_row.slug;
    IF FOUND THEN
      IF v_existing.owner_id IS DISTINCT FROM v_owner OR v_existing.listing_metadata #>> '{apimarket,id}' IS DISTINCT FROM v_row.metadata->>'id'
      THEN RAISE EXCEPTION 'API.market listing identity collision: %',v_row.slug; END IF;
      CONTINUE; -- Never republish a listing an operator has hidden or suspended.
    END IF;
    v_id:=gen_random_uuid();
    PERFORM set_config('apiosk.api_review_approved_id',v_id::text,true);
    INSERT INTO providers.apis(id,owner_id,slug,name,description,origin_url,endpoint_url,docs_url,website_url,
      category,source,listing_type,integration_mode,settlement_mode,requires_payout_wallet,is_external,
      commission_rate,status,active,discoverable,is_verified,verified_at,approved_at,authentication_info,listing_metadata)
    VALUES(v_id,v_owner,v_row.slug,left(v_row.name,160),left(v_row.description,600),'https://api.market',NULL,v_row.url,v_row.url,
      'business','api-market-catalog','federated','federated','invoice',false,true,
      0,'active',true,true,true,now(),now(),
      '{"type":"api_key","location":"header","name":"x-api-market-key","configured":false}'::jsonb,
      jsonb_build_object('provider_network','API.market','source','api-market-catalog','catalog_only',true,
        'resell',jsonb_build_object('enabled',false),
        'tags',jsonb_build_array('api-market','business-apis') || (v_row.metadata->'categories'),
        'sectors',jsonb_build_array('Business'),
        'coverage_notice','API.market catalog listing only. An API.market connection, current pricing and validated endpoint contracts are required before execution in Apiosk.',
        'execution_status','not_configured','apimarket',v_row.metadata));
    PERFORM set_config('apiosk.api_review_approved_id','',true);
  END LOOP;
END $onboard$;
